drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · reset counters in a list                                ★☆☆ core
//  concepts: struct copies · List indexer · write-back
// ─────────────────────────────────────────────────────────────────────────
//
//  Counter is a struct: every read through the indexer is a copy.

using static Bootcamp.Check;

void ResetAll(List<Counter> counters)
{
    for (int i = 0; i < counters.Count; i++)
    {
        var c = counters[i];
        c.Count = 0;
        counters[i] = c;
    }
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("every count becomes 0", () =>
{
    var xs = new List<Counter> { new("signups", 3), new("logins", 9) };
    ResetAll(xs);
    Eq(xs.Select(c => c.Count).ToList(), new[] { 0, 0 });
});

Test("names and order are kept", () =>
{
    var xs = new List<Counter> { new("signups", 3), new("logins", 9) };
    ResetAll(xs);
    Eq(xs.Select(c => c.Name).ToList(), new[] { "signups", "logins" });
});

Test("a counter already at 0 stays 0", () =>
{
    var xs = new List<Counter> { new("errors", 0) };
    ResetAll(xs);
    Eq(xs[0].Count, 0);
});

Test("an empty list stays empty (boundary)", () =>
{
    var xs = new List<Counter>();
    ResetAll(xs);
    Eq(xs.Count, 0);
});

drills.tail:
// ──────────────────────────── types ──────────────────────────────────────

struct Counter
{
    public Counter(string name, int count) { Name = name; Count = count; }
    public string Name;
    public int Count;
}

drills.explanation:
The indexer returns a copy, so read it into a local, change the local and store it back:

```csharp
for (int i = 0; i < counters.Count; i++)
{
    var c = counters[i];
    c.Count = 0;
    counters[i] = c;
}
```

A `foreach (var c in counters) c.Count = 0;` does not compile (the iteration variable is read-only), and copying into a local without the write-back silently changes nothing. Had `Counter` been a class, `counters[i].Count = 0` would have worked, because the list would hold references.

