drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · copy a cart                                             ★★☆ core
//  concepts: reference copies · shallow vs deep copy
// ─────────────────────────────────────────────────────────────────────────
//
//  Cart is a class with a List<string> inside: copy it without sharing the list.

using static Bootcamp.Check;

Cart CopyCart(Cart cart)
{
    return new Cart { Owner = cart.Owner, Items = new List<string>(cart.Items) };
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("the copy has the same owner and items", () =>
{
    var cart = new Cart { Owner = "ana", Items = new List<string> { "pen", "ink" } };
    var copy = CopyCart(cart);
    Eq(copy.Owner, "ana");
    Eq(copy.Items, new[] { "pen", "ink" });
});

Test("the copy is a different Cart object", () =>
{
    var cart = new Cart { Owner = "ana", Items = new List<string> { "pen" } };
    Ok(!ReferenceEquals(CopyCart(cart), cart), "CopyCart must return a new Cart");
});

Test("adding to the copy leaves the original alone", () =>
{
    var cart = new Cart { Owner = "ana", Items = new List<string> { "pen", "ink" } };
    var copy = CopyCart(cart);
    copy.Items.Add("pad");
    Eq(cart.Items, new[] { "pen", "ink" });
});

Test("clearing the original leaves the copy alone", () =>
{
    var cart = new Cart { Owner = "ana", Items = new List<string> { "pen" } };
    var copy = CopyCart(cart);
    cart.Items.Clear();
    Eq(copy.Items, new[] { "pen" });
});

Test("an empty cart copies to an empty cart (boundary)", () =>
{
    var cart = new Cart { Owner = "bo" };
    var copy = CopyCart(cart);
    Eq(copy.Items.Count, 0);
    Ok(!ReferenceEquals(copy.Items, cart.Items), "the copy needs its own list");
});

